		engine = 'postgres',
		size = 24,
		class: className = '',
		useInternetImage = true
	}: Props = $props();

	let imageError = $state(false);

	const normalizedEngine = $derived.by(() => {
		const eng = (engine || '').toLowerCase().trim();
		if (eng.includes('postgres') || eng === 'pgsql' || eng === 'psql') return 'postgres';
		if (eng.includes('mariadb')) return 'mariadb';
		if (eng.includes('mysql')) return 'mysql';
		if (eng.includes('redis') || eng.includes('valkey')) return 'redis';
		if (eng.includes('mongo')) return 'mongodb';
		if (eng.includes('clickhouse')) return 'clickhouse';
		if (eng.includes('libsql') || eng.includes('sqlite') || eng.includes('turso')) return 'libsql';
		return 'custom';
	});

	const internetImageUrls: Record<string, string> = {
		postgres:
			'https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/postgresql/postgresql-original.svg',
		mysql: 'https://cdn.jsdelivr.net/gh/devicons/devicon@latest/icons/mysql/mysql-original.svg',
		mariadb:
